#!/usr/bin/env python3
"""Generate Go services, the endpoint catalog, and the coverage reference."""
import json
from pathlib import Path
import subprocess
import sys
ROOT=Path(__file__).resolve().parents[1]
ops=json.loads((ROOT/'api/catalog.json').read_text())
failures=[]
def write_generated(path,text):
    if path.suffix=='.go':
        text=subprocess.run(['gofmt'],input=text,text=True,capture_output=True,check=True).stdout
    if '--check' in sys.argv:
        if not path.exists() or path.read_text()!=text: failures.append(str(path.relative_to(ROOT)))
    else: path.write_text(text)

def quote(s):return json.dumps(s)
services={'system':'System','auth':'Auth','hid':'HID','atx':'ATX','msd':'MSD','gpio':'GPIO','streamer':'Streamer','switch':'Switch','redfish':'Redfish','alerts':'Alerts','media':'Media','video':'Video','events':'Events'}
header='// Code generated by scripts/generate-api.py; DO NOT EDIT.\npackage pikvm\n\n'
s=header+'// Endpoints returns a fresh catalog of audited API operations.\nfunc Endpoints() []Endpoint { return []Endpoint{\n'
for x in ops:
 s+='{'+','.join(k+':'+quote(x[v]) for k,v in [('Group','group'),('Name','name'),('Method','method'),('Path','path'),('Description','description'),('ContentType','content_type')])+','
 s+='Parameters:[]string{'+','.join(quote(p) for p in x['parameters'])+'},'
 s+='BodyParameters:[]BodyParameter{'+','.join('{Name:'+quote(p['name'])+',Flag:'+quote(p['flag'])+',Type:'+quote(p['type'])+',Required:'+str(p['required']).lower()+'}' for p in x['body_parameters'])+'},'
 s+=','.join(k+':'+str(x[v]).lower() for k,v in [('BodyRequired','body_required'),('StreamResponse','stream_response'),('WebSocket','websocket')])+'},\n'
s+='} }\n';write_generated(ROOT/'lib/pikvm/endpoints.go',s)
s=header+'import("context"; "encoding/json"; "io"; "net/http"; "net/url"; "fmt"; "strings")\n\n// Result retains the complete JSON response, including firmware-specific fields.\ntype Result = json.RawMessage\n\n'
for g,name in services.items():
 s+=f'// {name}Service provides {g} API operations.\ntype {name}Service struct {{ client *Client }}\n// {name} returns the {g} API service.\nfunc (c *Client) {name}() *{name}Service {{ return &{name}Service{{client:c}} }}\n\n'
 for x in ops:
  if x['group']!=g:continue
  method=''.join(w.capitalize() for w in x['name'].split('-'));path=x['path'];verb=x['method']
  args='ctx context.Context, options url.Values';callpath=quote(path);pre=''
  if '{id}' in path:
   args='ctx context.Context, id string, options url.Values';pre='if id == "" || strings.ContainsAny(id,"/?#") { return nil, fmt.Errorf("invalid system id") }; '
   callpath='strings.ReplaceAll('+quote(path)+',"{id}",url.PathEscape(id))'
  hasbody=bool(x['content_type'])
  if x['websocket']:
   s+=f'// {method} opens {path}. Close the session after use.\nfunc (s *{name}Service) {method}({args}) (*Session,error) {{ return s.client.Dial(ctx,{callpath},options) }}\n\n';continue
  if hasbody:args+=', body io.Reader'
  call=f's.client.Request(ctx,{quote(verb)},{callpath},options,'+('body' if hasbody else 'nil')+','+quote(x['content_type'])+')'
  if x['stream_response'] or hasbody:
   s+=f'// {method} calls {verb} {path}. The caller must close the response body.\nfunc (s *{name}Service) {method}({args}) (*http.Response,error) {{ {pre}return {call} }}\n\n'
  else:
   s+=f'// {method} calls {verb} {path}. Options use API query names.\nfunc (s *{name}Service) {method}({args}) (Result,error) {{ {pre}r,err:={call};if err!=nil{{return nil,err}};defer r.Body.Close();data,err:=io.ReadAll(r.Body);return Result(data),err }}\n\n'
write_generated(ROOT/'lib/pikvm/services.go',s)
doc='# API coverage\n\nGenerated from `api/catalog.json`. KVMD route and parameter inventory is independently extracted in `api/upstream.json` from official KVMD commit `fe26d028fc493942e2f951f8cd487cd5163238e3`. All 15 inbound WebSocket handlers (including binary protocol layouts and helper implementations) are pinned by AST fingerprints. uStreamer HTTP operations are audited against `296639a2acd06f8f39131e2d27170caccf8fd63a`.\n\n'+f'{len(ops)} routes: {sum(not x["websocket"] for x in ops)} HTTP operations and {sum(x["websocket"] for x in ops)} WebSocket upgrades. Each has a named library service method and CLI command.\n\n| HTTP | Path | Command | Query/path parameters | Form/JSON fields |\n| --- | --- | --- | --- | --- |\n'
for x in ops:
 doc+='| '+x['method']+' | `'+x['path']+'` | `'+x['group']+' '+x['name']+'` | '+', '.join('`'+p+'`' for p in x['parameters'])+' | '+', '.join('`'+p['name']+'`' for p in x['body_parameters'])+' |\n'
doc+='\n`*` denotes required query parameters. Body fields can be supplied with the named flags shown by `--help` or through `--body`/`--input`. Login uses form fields; Redfish uses JSON. `id` selects the Redfish system path and defaults to `0`.\n\nBoth WebSocket commands accept every event through `--event-type`/`--event` and every binary opcode through `--binary-input`. `events` also has named ping, key, button, move, relative, wheel and binary subcommands. `media` has start, ping and keyframe subcommands.\n\nScope: the APIs served by main KVMD and KVMD-Media through PiKVM Nginx, plus uStreamer state/snapshot/MJPEG. Janus WebRTC signaling belongs to the separate Janus server and is outside the REST API inventory, as are optional third-party extras and internal Unix-socket daemons. Endpoint availability still depends on installed firmware and hardware. This is endpoint/parameter parity, not a claim of 100% code coverage or live hardware validation.\n\nTo audit a newer checkout, run `python3 scripts/audit-api.py /path/to/kvmd /path/to/ustreamer`. A difference fails with an inventory diff. Update the pinned inventory and catalog after review, then run `python3 scripts/generate-api.py` and `go test -race ./...`. Normal tests run offline against the pinned inventory.\n'
write_generated(ROOT/'api/COVERAGE.md',doc)
if failures:
    raise SystemExit('Generated artifacts are stale: '+', '.join(failures)+'; run python3 scripts/generate-api.py')
